```python
import json
from dataclasses import dataclass, field
from typing import List

# Define data classes
@dataclass
class DeviceMeta:
    agl: float
    name: str
    environment: str
    wifi_network_name: str

@dataclass
class Device:
    device_id: int
    serial_number: str
    device_meta: DeviceMeta
    device_type: str
    hardware_revision: str
    firmware_revision: str
    notes: str

@dataclass
class StationMeta:
    elevation: float
    share_with_wf: bool
    share_with_wu: bool

@dataclass
class StationItem:
    location_item_id: int
    station_id: int
    device_id: int
    item: str

@dataclass
class Location:
    station_id: int
    name: str
    public_name: str
    latitude: float
    longitude: float
    station_meta: StationMeta
    devices: List[Device]
    station_items: List[StationItem]

@dataclass
class Status:
    status_code: int
    status_message: str

@dataclass
class JsonResponse:
    status: Status
    locations: List[Location]

# Function to parse JSON data into data classes
def parse_json(json_data):
    def _from_dict(data_class, data):
        fields = {f.name: data.get(f.name) for f in dataclass.fields(data_class)}
        return data_class(**fields)
    
    return _from_dict(JsonResponse, json_data)

# Example JSON data (as a string)
json_str = '''{
  "status": {
    "status_code": 0,
    "status_message": "SUCCESS"
  },
  "locations": [
    {
      "station_id": 67,
      ...
    }
  ]
}'''

# Load and parse JSON data
data = json.loads(json_str)
parsed_data = parse_json(data)

# Now you can access the data through the data class instances
print(parsed_data.status.status_message)  # Example usage
```

